                    const v = k.rb(e0);
                    const e1: u32 = k.a[6] +% @as(u32, 1);
                    k.wb(e1, v);
                    k.logic(u8, v);
                }
                // $0b3d6  move.b -$1(a6), $2(a6)
                {
                    k.cy +%= 20;
                    const e0: u32 = k.a[6] +% @as(u32, @bitCast(@as(i32, -1)));
                    const v = k.rb(e0);
                    const e1: u32 = k.a[6] +% @as(u32, 2);
                    k.wb(e1, v);
                    k.logic(u8, v);
                }
                // $0b3dc  suba.l #$e, a4
                {
                    k.cy +%= 12;
                    k.a[4] -%= @as(u32, 0xe);
                }
                // $0b3e2  suba.l #$4, a5
                {
                    k.cy +%= 12;
                    k.a[5] -%= @as(u32, 0x4);
                }
                // $0b3e8  suba.l #$3, a6
                {
                    k.cy +%= 12;
                    k.a[6] -%= @as(u32, 0x3);
                }
                // $0b3ee  jmp $1b394.l
                {
                    k.cy +%= 20;
                    { if (k.cy >= k.limit) return 0x1b394; continue :sw 0x1b394; }
                }
            },
            else => return k.bad(pc),
        }
    }

};

